/**
 * Customer-facing documents (resumes, cover letters, selection-criteria responses) go to
 * employers. They must never carry "AI Resume"-style titles, "generated by ..." credits or
 * model names. This is the server-side backstop: it runs on ALL model output before it is
 * saved or exported, whatever the prompt said.
 *
 * A phrase the candidate wrote themselves ("Built an AI resume parser") is their own content,
 * not branding: pass the source text as `allowFrom` and matches found there are left alone.
 */

interface Rule {
  re: RegExp;
  /** Replacement. A string with $1.. refers to capture groups. */
  to: string | ((m: string, ...g: string[]) => string);
}

const MODEL = "chat\\s?gpt|gpt-?\\d[\\w.-]*|open\\s?ai|anthropic|claude(?:[\\s-](?:ai|sonnet|opus|haiku|\\d[\\w.-]*))|gemini|copilot|llm|large language model|artificial intelligence|a\\.i\\.|ai";

const RULES: Rule[] = [
  // "AI Resume", "AI-Generated Cover Letter", "AI Tailored CV" → plain titles.
  {
    re: /\b(?:a\.?i\.?|artificial intelligence)[\s-]*(?:generated|powered|written|assisted|created|tailored|optimi[sz]ed|enhanced)?[\s-]*(resume|cover letter|curriculum vitae|cv)\b/gi,
    to: (_m, kind: string) => (/cover/i.test(kind) ? "Cover Letter" : /^cv$/i.test(kind) ? "CV" : "Resume"),
  },
  // "Tailored Resume" scaffolding label echoed as a title.
  { re: /^\s*(?:tailored\s+)(resume|cover letter)\s*:?\s*$/gim, to: "" },
  // "Generated by ChatGPT", "— written with Claude", "Created using AI", "(Made with ResumeTailored AI)".
  {
    re: new RegExp(`[\\s,;:|\\u2014\\u2013(\\[-]*\\b(?:generated|written|created|produced|made|drafted|tailored|powered|assisted|composed)\\s+(?:by|with|using|via|from)\\s+(?:an?\\s+|the\\s+)?(?:resume\\s?tailored(?:\\s+ai)?|${MODEL})\\b(?:\\s+(?:model|assistant|tool|chatbot))?[)\\]]?(?:\\s*[·|]\\s*resumetailored\\.com)?`, "gi"),
    to: "",
  },
  { re: /\bmade with resume\s?tailored(?:\s+ai)?(?:\s*[·|]\s*resumetailored\.com)?/gi, to: "" },
  { re: /\bresume\s?tailored\s+ai\b/gi, to: "" },
  { re: /\b(?:as an? (?:ai|language model)|ai[- ]generated(?: content)?)\b/gi, to: "" },
  // Bare model / vendor names.
  { re: /\b(?:chat\s?gpt|openai|anthropic|claude[\s-](?:ai|sonnet|opus|haiku|\d[\w.-]*)|gpt-?\d[\w.-]*)\b/gi, to: "" },
];

/** Every banned pattern found in `text` (empty array = clean). Matches present in `allowFrom` are ignored. */
export function findBanned(text: string, allowFrom = ""): string[] {
  const hits: string[] = [];
  const allow = allowFrom.toLowerCase();
  for (const r of RULES) {
    const re = new RegExp(r.re.source, r.re.flags.includes("g") ? r.re.flags : r.re.flags + "g");
    let m: RegExpExecArray | null;
    while ((m = re.exec(text))) {
      const s = m[0].trim();
      if (m[0] === "") { re.lastIndex++; continue; }
      if (s && !(allow && allow.includes(s.toLowerCase()))) hits.push(s);
    }
  }
  return hits;
}

function tidy(s: string): string {
  return s
    .replace(/[ \t]{2,}/g, " ")
    .replace(/[ \t]+([,.;:!?])/g, "$1")
    .replace(/[ \t]+$/gm, "")
    .replace(/^[ \t]*[|·—–-][ \t]*$/gm, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

/** Strip banned branding from one string. Phrases that also appear in `allowFrom` are preserved. */
export function scrubText(text: string, allowFrom = ""): string {
  if (!text) return text;
  const allow = allowFrom.toLowerCase();
  let out = text;
  for (const r of RULES) {
    out = out.replace(r.re, (...args: unknown[]) => {
      const m = args[0] as string;
      if (allow && allow.includes(m.trim().toLowerCase())) return m;
      return typeof r.to === "string" ? r.to : (r.to as (m: string, ...g: string[]) => string)(m, ...(args.slice(1) as string[]));
    });
  }
  return tidy(out);
}

/** Scrub every string inside a JSON-like value (objects, arrays), returning a copy. */
export function scrubDeep<T>(value: T, allowFrom = ""): T {
  if (typeof value === "string") return scrubText(value, allowFrom) as unknown as T;
  if (Array.isArray(value)) return value.map((v) => scrubDeep(v, allowFrom)) as unknown as T;
  if (value && typeof value === "object") {
    const o: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) o[k] = scrubDeep(v, allowFrom);
    return o as T;
  }
  return value;
}
